WITH integrity AS MATERIALIZED (SELECT CASE WHEN NOT system.main.td_control_check_v1(CAST($1 AS BIGINT)) THEN error('TD_E_CONTROL: invalid invocation') WHEN system.main.td_owner_probe_validated_check() IS NOT TRUE THEN error('TD_E_OWNER_PROBE_INVALID: owner scope is not audited') WHEN NOT (SELECT ok FROM (SELECT CASE
 WHEN (SELECT count(*) FROM main.store_meta)<>1 OR EXISTS(
   SELECT 1 FROM main.store_meta WHERE version IS NULL OR version NOT IN(5,6,8,9,10,11))
 THEN error('TD_E_COMMAND_FORMAT: unsupported native store format')
 WHEN (SELECT count(*) FROM td_catalog_v1.catalog_revision)>1 OR EXISTS(
   SELECT 1 FROM td_catalog_v1.catalog_revision WHERE singleton IS DISTINCT FROM TRUE OR revision IS NULL OR revision NOT IN(2,3))
 THEN error('TD_E_COMMAND_FORMAT: unsupported native catalog revision')
 WHEN EXISTS(SELECT 1 FROM main.store_meta m WHERE CASE m.version
   WHEN 5 THEN EXISTS(SELECT 1 FROM td_catalog_v1.catalog_revision WHERE revision<>2)
   WHEN 9 THEN (SELECT count(*) FROM td_catalog_v1.catalog_revision)<>1
   WHEN 10 THEN (SELECT count(*) FROM td_catalog_v1.catalog_revision)<>1
   WHEN 11 THEN (SELECT count(*) FROM td_catalog_v1.catalog_revision)<>1
   ELSE (SELECT count(*) FROM td_catalog_v1.catalog_revision WHERE revision=2)<>1 END)
 THEN error('TD_E_COMMAND_FORMAT: native format/catalog revision mismatch')
 ELSE TRUE END ok) native_format) THEN error('TD_E_COMMAND_FORMAT: unsupported native catalog') WHEN (SELECT count(*) FROM system.main.pragma_database_list)<>1 THEN error('TD_E_QUERY_CATALOG: visible extra attachments are unsupported') WHEN system.main.td_float_from_bits_v1('0000000000000000')<>0 THEN error('TD_E_QUERY_PROFILE: invalid float codec') ELSE TRUE END ok),cuts AS MATERIALIZED (SELECT '0'::BIGINT valid,(SELECT CASE WHEN position<586 THEN error('TD_E_QUERY_INPUT: knowledge cut exceeds committed clock') ELSE 586 END FROM main.clock WHERE singleton)::BIGINT known FROM integrity WHERE ok),owner_cap AS MATERIALIZED (SELECT system.main.td_owner_probe_uniqueness_check() capabilities),input_statistics AS MATERIALIZED (SELECT count(*) n,count(*) FILTER(WHERE v_tag>8 OR octet_length(encode(e))>512 OR octet_length(encode(a))>512 OR (v_tag IN(1,5,8) AND octet_length(v_s)>512) OR (v_tag=8 AND octet_length(v_s)=0) OR CASE WHEN v_tag=7 THEN CASE WHEN octet_length(v_s)>4096 THEN TRUE ELSE system.main.td_validate_json_source_v2(decode(v_s)) IS NOT TRUE END ELSE FALSE END) invalid,coalesce(sum(120::HUGEINT+octet_length(encode(e))+octet_length(encode(a))+CASE WHEN v_tag IN(1,5,7,8) THEN octet_length(v_s) ELSE 0 END),0) carrier_bytes FROM main.assertions CROSS JOIN cuts WHERE valid_from<=valid AND valid<valid_to AND tx_from<=known AND known<tx_to AND (a COLLATE "binary" IN ('i','probe_member'))),admission AS MATERIALIZED (SELECT CASE WHEN invalid>0 THEN error('TD_E_QUERY_PROFILE: relevant data exceeds the eight-tag Datalog profile (512-byte text/ID and 4096-byte strict JSON)') WHEN n>124696 OR n>124696 OR carrier_bytes>4294967296 THEN error('TD_E_QUERY_SCALE_LIMIT: scalable SQL input exceeds logical budget') ELSE TRUE END ok FROM input_statistics CROSS JOIN integrity),active AS MATERIALIZED (SELECT e,a,v_tag,v_s,v_b,v_i,v_f FROM main.assertions CROSS JOIN cuts CROSS JOIN admission CROSS JOIN owner_cap WHERE admission.ok AND (owner_cap.capabilities & 2)<>0 AND valid_from<=valid AND valid<valid_to AND tx_from<=known AND known<tx_to AND (a COLLATE "binary" IN ('i','probe_member')) UNION ALL SELECT DISTINCT e,a,v_tag,v_s,v_b,v_i,v_f FROM main.assertions CROSS JOIN cuts CROSS JOIN admission CROSS JOIN owner_cap WHERE admission.ok AND (owner_cap.capabilities & 2)=0 AND valid_from<=valid AND valid<valid_to AND tx_from<=known AND known<tx_to AND (a COLLATE "binary" IN ('i','probe_member'))),statistics AS MATERIALIZED (SELECT count(*) n,coalesce(sum(octet_length(encode(e))+octet_length(encode(a))+CASE WHEN v_tag IN(1,5,7,8) THEN octet_length(v_s) ELSE 0 END),0) string_bytes,coalesce(max(octet_length(encode(e))),0) e_bytes,coalesce(max(octet_length(encode(a))),0) a_bytes,coalesce(max(CASE WHEN v_tag IN(1,5,7,8) THEN octet_length(v_s) ELSE 0 END),0) v_bytes FROM active),mode AS MATERIALIZED (SELECT CASE WHEN NOT (statistics.n*120::HUGEINT+statistics.string_bytes<=4294967296 AND (SELECT count(*) FROM active WHERE TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(a) IS NOT DISTINCT FROM encode('probe_member') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE)<=124696 AND (SELECT count(*) FROM active WHERE TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(a) IS NOT DISTINCT FROM encode('probe_member') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE)*(120::HUGEINT+40+0+statistics.e_bytes)<=4294967296) THEN error('TD_E_QUERY_SCALE_LIMIT: scalable SQL intermediate exceeds logical budget') WHEN NOT (TRUE) THEN error('TD_E_QUERY_SCALE_UNSUPPORTED: scalable SQL aggregate domain is unproved') WHEN ((SELECT count(*) FROM active WHERE TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(a) IS NOT DISTINCT FROM encode('probe_member') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE))>100000 OR ((SELECT count(*) FROM active WHERE TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(a) IS NOT DISTINCT FROM encode('probe_member') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE))*(384+6*(0+statistics.e_bytes))>16777216 THEN error('TD_E_QUERY_SCALE_LIMIT: scalable SQL output exceeds logical budget') ELSE TRUE END use_sql FROM statistics CROSS JOIN admission CROSS JOIN integrity),anti_input AS MATERIALIZED (SELECT * FROM active WHERE (SELECT use_sql FROM mode)),anti_positive AS MATERIALIZED (SELECT kept.* FROM anti_input kept WHERE TRUE AND (TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(kept.a) IS NOT DISTINCT FROM encode('probe_member') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE)),anti_relevant_denied AS MATERIALIZED (SELECT denied.* FROM anti_input denied SEMI JOIN anti_positive kept ON TRUE AND (TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(denied.e) IS NOT DISTINCT FROM encode(kept.e) AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE) AND (TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(denied.a) IS NOT DISTINCT FROM encode('i') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE) AND (TRUE AND denied.v_tag IS NOT DISTINCT FROM kept.v_tag AND denied.v_s IS NOT DISTINCT FROM kept.v_s AND denied.v_b IS NOT DISTINCT FROM kept.v_b AND denied.v_i IS NOT DISTINCT FROM kept.v_i AND denied.v_f IS NOT DISTINCT FROM kept.v_f)),anti_active AS (SELECT kept.* FROM anti_positive kept ANTI JOIN anti_relevant_denied denied ON TRUE AND (TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(denied.e) IS NOT DISTINCT FROM encode(kept.e) AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE) AND (TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(denied.a) IS NOT DISTINCT FROM encode('i') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE) AND (TRUE AND denied.v_tag IS NOT DISTINCT FROM kept.v_tag AND denied.v_s IS NOT DISTINCT FROM kept.v_s AND denied.v_b IS NOT DISTINCT FROM kept.v_b AND denied.v_i IS NOT DISTINCT FROM kept.v_i AND denied.v_f IS NOT DISTINCT FROM kept.v_f)),sql_answer AS MATERIALIZED (SELECT DISTINCT TRUE present,1::UTINYINT h0t,encode(e) h0s,NULL::BOOLEAN h0b,NULL::BIGINT h0i,NULL::DOUBLE h0f FROM anti_active WHERE (SELECT use_sql FROM mode) AND TRUE AND 1::UTINYINT IS NOT DISTINCT FROM 1::UTINYINT AND encode(a) IS NOT DISTINCT FROM encode('probe_member') AND NULL::BOOLEAN IS NOT DISTINCT FROM NULL::BOOLEAN AND NULL::BIGINT IS NOT DISTINCT FROM NULL::BIGINT AND NULL::DOUBLE IS NOT DISTINCT FROM NULL::DOUBLE) SELECT known,'sql' route,CASE WHEN ((SELECT capabilities FROM owner_cap) & 2)<>0 THEN 'owned_allcut_unique_scalable_anti_join' ELSE 'owned_scalable_anti_join' END reason,NULL::BIGINT rounds,NULL::BIGINT derived_facts,NULL::BIGINT work,CASE WHEN r.present THEN CAST(to_json([struct_pack(tag:=r.h0t,s:=decode(r.h0s),b:=r.h0b,i:=r.h0i::VARCHAR,f:=CASE WHEN r.h0t IN(4,6) THEN system.main.td_float_bits_v1(r.h0f) END)]) AS VARCHAR) END tuple_json FROM cuts CROSS JOIN mode LEFT JOIN sql_answer r ON TRUE WHERE use_sql ORDER BY r.h0t,r.h0s,r.h0b,r.h0i,r.h0f